#define _WIN32_WINNT 0x0A00
#include "settings.h"
#include <windows.h>
#include <shlobj.h>
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { char *s; size_t n, cap; } SBuf;
static void errset(char *out,size_t cap,const char *s){if(out&&cap){snprintf(out,cap,"%s",s?s:"Error");out[cap-1]='\0';}}
static int addn(SBuf*b,const char*s,size_t n){if(n>(size_t)-1-b->n-1)return 0;size_t need=b->n+n+1;if(need>b->cap){size_t c=b->cap?b->cap:256;while(c<need)c=c>(size_t)-1/2?need:c*2;char*p=(char*)realloc(b->s,c);if(!p)return 0;b->s=p;b->cap=c;}memcpy(b->s+b->n,s,n);b->n+=n;b->s[b->n]=0;return 1;}
static int adds(SBuf*b,const char*s){return s?addn(b,s,strlen(s)):1;}
static int cpadd(SBuf*b,unsigned cp){char x[4];size_t n;if(cp<0x80){x[0]=(char)cp;n=1;}else if(cp<0x800){x[0]=(char)(0xc0|(cp>>6));x[1]=(char)(0x80|(cp&63));n=2;}else if(cp<0x10000){x[0]=(char)(0xe0|(cp>>12));x[1]=(char)(0x80|((cp>>6)&63));x[2]=(char)(0x80|(cp&63));n=3;}else{x[0]=(char)(0xf0|(cp>>18));x[1]=(char)(0x80|((cp>>12)&63));x[2]=(char)(0x80|((cp>>6)&63));x[3]=(char)(0x80|(cp&63));n=4;}return addn(b,x,n);}
static wchar_t *wide(const char*s){if(!s)return NULL;int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s,-1,NULL,0);if(!n)return NULL;wchar_t*p=(wchar_t*)malloc((size_t)n*sizeof(*p));if(!p)return NULL;if(!MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s,-1,p,n)){free(p);return NULL;}return p;}
static int utf8_from_wide(const wchar_t*s,char*out,size_t cap){int n=WideCharToMultiByte(CP_UTF8,0,s,-1,NULL,0,NULL,NULL);if(n<=0||(size_t)n>cap)return 0;return WideCharToMultiByte(CP_UTF8,0,s,-1,out,(int)cap,NULL,NULL)>0;}
static int path_join(char*out,size_t cap,const char*a,const char*b){size_t n=strlen(a);while(n&&(a[n-1]=='\\'||a[n-1]=='/'))n--;int w=snprintf(out,cap,"%.*s\\%s",(int)n,a,b);return w>=0&&(size_t)w<cap;}
int zd_ensure_directory_utf8(const char*path){wchar_t*w=wide(path);if(!w)return 0;int rc=SHCreateDirectoryExW(NULL,w,NULL);free(w);return rc==ERROR_SUCCESS||rc==ERROR_ALREADY_EXISTS||rc==ERROR_FILE_EXISTS;}
void zd_settings_defaults(ZDSettings*s){if(!s)return;memset(s,0,sizeof(*s));s->request_timeout_connect=10;s->request_timeout_read=30;s->max_retry_attempts=3;strcpy(s->log_level,"INFO");strcpy(s->theme,"light");strcpy(s->ui_mode,"user");strcpy(s->language,"uk");}
int zd_paths_init(ZDPaths*p,char*error,size_t cap){if(error&&cap)error[0]=0;if(!p){errset(error,cap,"Invalid path structure.");return 0;}memset(p,0,sizeof(*p));wchar_t profile[ZD_PATH_MAX];DWORD n=GetEnvironmentVariableW(L"USERPROFILE",profile,ZD_PATH_MAX);if(!n||n>=ZD_PATH_MAX){n=GetCurrentDirectoryW(ZD_PATH_MAX,profile);if(!n||n>=ZD_PATH_MAX){errset(error,cap,"Could not determine the Windows user folder.");return 0;}}char user[ZD_PATH_MAX];if(!utf8_from_wide(profile,user,sizeof(user))||!path_join(p->base,sizeof(p->base),user,"ZakonDownloader")||!path_join(p->data,sizeof(p->data),p->base,"data")||!path_join(p->documents,sizeof(p->documents),p->data,"documents")||!path_join(p->logs,sizeof(p->logs),p->data,"logs")||!path_join(p->exported,sizeof(p->exported),p->data,"exported_logs")||!path_join(p->history,sizeof(p->history),p->data,"history")||!path_join(p->config,sizeof(p->config),p->base,"config")||!path_join(p->settings_file,sizeof(p->settings_file),p->config,"settings.json")||!path_join(p->history_db,sizeof(p->history_db),p->history,"history.db")){errset(error,cap,"Windows user path is too long.");return 0;}if(!zd_ensure_directory_utf8(p->documents)||!zd_ensure_directory_utf8(p->logs)||!zd_ensure_directory_utf8(p->exported)||!zd_ensure_directory_utf8(p->history)||!zd_ensure_directory_utf8(p->config)){errset(error,cap,"Could not create the ZakonDownloader data folders.");return 0;}return 1;}
static const char*json_value(const char*json,const char*key){char token[96];int n=snprintf(token,sizeof(token),"\"%s\"",key);if(n<0||(size_t)n>=sizeof(token))return NULL;const char*p=strstr(json,token);if(!p)return NULL;p+=strlen(token);while(isspace((unsigned char)*p))p++;if(*p++!=':')return NULL;while(isspace((unsigned char)*p))p++;return p;}
static int hex4(const char*p,unsigned*out){unsigned v=0;for(int i=0;i<4;i++){int c=(unsigned char)p[i];int d=isdigit(c)?c-'0':(tolower(c)>='a'&&tolower(c)<='f'?tolower(c)-'a'+10:-1);if(d<0)return 0;v=v*16+(unsigned)d;}*out=v;return 1;}
static int json_string(const char*json,const char*key,char*out,size_t cap){const char*p=json_value(json,key);if(!p||*p!='"'||!cap)return 0;p++;SBuf b={0};while(*p&&*p!='"'){unsigned char c=(unsigned char)*p++;if(c=='\\'){char e=*p++;if(!e)goto fail;switch(e){case '"':case '\\':case '/':if(!addn(&b,&e,1))goto fail;break;case 'b':e='\b';if(!addn(&b,&e,1))goto fail;break;case 'f':e='\f';if(!addn(&b,&e,1))goto fail;break;case 'n':e='\n';if(!addn(&b,&e,1))goto fail;break;case 'r':e='\r';if(!addn(&b,&e,1))goto fail;break;case 't':e='\t';if(!addn(&b,&e,1))goto fail;break;case 'u':{unsigned u;if(!hex4(p,&u))goto fail;p+=4;if(u>=0xd800&&u<=0xdbff&&p[0]=='\\'&&p[1]=='u'){unsigned lo;if(hex4(p+2,&lo)&&lo>=0xdc00&&lo<=0xdfff){u=0x10000+((u-0xd800)<<10)+(lo-0xdc00);p+=6;}}if(!cpadd(&b,u))goto fail;break;}default:goto fail;}}else if(!addn(&b,(const char*)&c,1))goto fail;}if(*p!='"'||b.n>=cap)goto fail;if(b.s)memcpy(out,b.s,b.n+1);else out[0]=0;free(b.s);return 1;fail:free(b.s);return 0;}
static int json_int(const char*json,const char*key,int fallback,int min,int max){const char*p=json_value(json,key);if(!p)return fallback;char*end=NULL;long n=strtol(p,&end,10);if(end==p)return fallback;if(n<min)n=min;if(n>max)n=max;return(int)n;}
int zd_settings_load(const char*path,ZDSettings*s,char*error,size_t cap){if(error&&cap)error[0]=0;if(!s||!path){errset(error,cap,"Invalid settings path.");return 0;}zd_settings_defaults(s);wchar_t*w=wide(path);if(!w){errset(error,cap,"Invalid UTF-8 settings path.");return 0;}HANDLE h=CreateFileW(w,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);free(w);if(h==INVALID_HANDLE_VALUE){if(GetLastError()==ERROR_FILE_NOT_FOUND||GetLastError()==ERROR_PATH_NOT_FOUND)return 1;errset(error,cap,"Could not read settings.json.");return 0;}LARGE_INTEGER size;if(!GetFileSizeEx(h,&size)||size.QuadPart<0||size.QuadPart>1024*1024){CloseHandle(h);errset(error,cap,"Settings file is too large.");return 0;}size_t n=(size_t)size.QuadPart;char*json=(char*)malloc(n+1);if(!json){CloseHandle(h);errset(error,cap,"Out of memory reading settings.");return 0;}DWORD got=0;BOOL ok=ReadFile(h,json,(DWORD)n,&got,NULL);CloseHandle(h);if(!ok||got!=n){free(json);errset(error,cap,"Could not read the complete settings file.");return 0;}json[n]=0;s->request_timeout_connect=json_int(json,"request_timeout_connect",10,1,300);s->request_timeout_read=json_int(json,"request_timeout_read",30,1,600);s->max_retry_attempts=json_int(json,"max_retry_attempts",3,1,10);json_string(json,"log_level",s->log_level,sizeof(s->log_level));json_string(json,"theme",s->theme,sizeof(s->theme));json_string(json,"ui_mode",s->ui_mode,sizeof(s->ui_mode));json_string(json,"language",s->language,sizeof(s->language));json_string(json,"documents_dir",s->documents_dir,sizeof(s->documents_dir));if(strcmp(s->theme,"light")&&strcmp(s->theme,"dark"))strcpy(s->theme,"light");if(strcmp(s->ui_mode,"user")&&strcmp(s->ui_mode,"developer"))strcpy(s->ui_mode,"user");if(strcmp(s->language,"uk")&&strcmp(s->language,"en")&&strcmp(s->language,"de")&&strcmp(s->language,"fr")&&strcmp(s->language,"es")&&strcmp(s->language,"pt")&&strcmp(s->language,"zh"))strcpy(s->language,"uk");if(strcmp(s->log_level,"INFO")&&strcmp(s->log_level,"WARNING")&&strcmp(s->log_level,"ERROR")&&strcmp(s->log_level,"DEBUG"))strcpy(s->log_level,"INFO");free(json);return 1;}
static int json_quote(SBuf*b,const char*s){if(!adds(b,"\""))return 0;for(const unsigned char*p=(const unsigned char*)(s?s:"");*p;p++){char x[7];switch(*p){case '"':if(!adds(b,"\\\""))return 0;break;case '\\':if(!adds(b,"\\\\"))return 0;break;case '\n':if(!adds(b,"\\n"))return 0;break;case '\r':if(!adds(b,"\\r"))return 0;break;case '\t':if(!adds(b,"\\t"))return 0;break;default:if(*p<0x20){snprintf(x,sizeof(x),"\\u%04x",*p);if(!adds(b,x))return 0;}else if(!addn(b,(const char*)p,1))return 0;}}return adds(b,"\"");}
int zd_settings_save(const char*path,const ZDSettings*s,char*error,size_t cap){if(error&&cap)error[0]=0;if(!path||!s){errset(error,cap,"Invalid settings.");return 0;}SBuf b={0};char num[160];snprintf(num,sizeof(num),"{\n  \"request_timeout_connect\": %d,\n  \"request_timeout_read\": %d,\n  \"max_retry_attempts\": %d,\n  \"log_level\": ",s->request_timeout_connect,s->request_timeout_read,s->max_retry_attempts);int ok=adds(&b,num)&&json_quote(&b,s->log_level)&&adds(&b,",\n  \"theme\": ")&&json_quote(&b,s->theme)&&adds(&b,",\n  \"documents_dir\": ")&&json_quote(&b,s->documents_dir)&&adds(&b,",\n  \"language\": ")&&json_quote(&b,s->language)&&adds(&b,",\n  \"ui_mode\": ")&&json_quote(&b,s->ui_mode)&&adds(&b,"\n}\n");if(!ok){free(b.s);errset(error,cap,"Out of memory serializing settings.");return 0;}wchar_t*w=wide(path);if(!w){free(b.s);errset(error,cap,"Invalid UTF-8 settings path.");return 0;}wchar_t tmp[ZD_PATH_MAX];int tn=swprintf(tmp,ZD_PATH_MAX,L"%ls.%lu.tmp",w,(unsigned long)GetCurrentProcessId());if(tn<0||(size_t)tn>=ZD_PATH_MAX){free(w);free(b.s);errset(error,cap,"Settings path is too long.");return 0;}HANDLE h=CreateFileW(tmp,GENERIC_WRITE,0,NULL,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE){free(w);free(b.s);errset(error,cap,"Could not create temporary settings file.");return 0;}DWORD wrote=0;ok=WriteFile(h,b.s,(DWORD)b.n,&wrote,NULL)&&wrote==(DWORD)b.n&&FlushFileBuffers(h);CloseHandle(h);if(ok)ok=MoveFileExW(tmp,w,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);if(!ok){DeleteFileW(tmp);errset(error,cap,"Could not atomically save settings.json.");}free(w);free(b.s);return ok?1:0;}
